import{_ as i,C as t,c as a,o as e,j as o,G as l,b as r,a0 as n,a as s,w as d,a1 as u}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Creare il tuo piano di allenamento","description":"","frontmatter":{},"headers":[],"relativePath":"it/education/goals/planning.md","filePath":"it/education/goals/planning.md"}');const p=i({name:"it/education/goals/planning.md"},[["render",function(i,c,p,m,g,h){const b=t("AdBanner"),v=t("Mermaid"),f=t("AdInArticle");return e(),a("div",null,[c[1]||(c[1]=o("h1",{id:"creare-il-tuo-piano-di-allenamento",tabindex:"-1"},[s("Creare il tuo piano di allenamento "),o("a",{class:"header-anchor",href:"#creare-il-tuo-piano-di-allenamento","aria-label":'Permalink to "Creare il tuo piano di allenamento"'},"​")],-1)),l(b),c[2]||(c[2]=o("p",null,"Gli obiettivi senza un piano sono solo desideri. Questa guida ti aiuta a trasformare i tuoi obiettivi in un piano di allenamento strutturato che funzioni davvero.",-1)),c[3]||(c[3]=o("div",{class:"tip custom-block"},[o("p",{class:"custom-block-title"},"La grande idea"),o("p",null,[o("strong",null,"Gli obiettivi senza un piano sono solo desideri."),s(" Un piano di allenamento strutturato trasforma i tuoi obiettivi in azioni quotidiane che si traducono in progressi concreti.")])],-1)),(e(),r(u,null,{default:d(()=>[l(v,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BObiettivo%5D%20--%3E%20B%5BPiano%20di%20allenamento%5D%0A%20%20%20%20B%20--%3E%20C%5BAzioni%20quotidiane%5D%0A%20%20%20%20C%20--%3E%20D%5BPratica%20coerente%5D%0A%20%20%20%20D%20--%3E%20E%5BProgresso%20misurabile%5D%0A%20%20%20%20E%20--%3E%20F%5BRaggiungimento%20dell%26%2339%3Bobiettivo%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23e8f5e9%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:d(()=>[...c[0]||(c[0]=[s(" Loading... ",-1)])]),_:1})),c[4]||(c[4]=n('<h2 id="le-8-fasi-dello-sviluppo-autodiretto" tabindex="-1">Le 8 fasi dello sviluppo autodiretto <a class="header-anchor" href="#le-8-fasi-dello-sviluppo-autodiretto" aria-label="Permalink to &quot;Le 8 fasi dello sviluppo autodiretto&quot;">​</a></h2><h3 id="fase-1-imposta-la-tua-bussola-obiettivi" tabindex="-1">Fase 1: Imposta la tua bussola (obiettivi) <a class="header-anchor" href="#fase-1-imposta-la-tua-bussola-obiettivi" aria-label="Permalink to &quot;Fase 1: Imposta la tua bussola (obiettivi)&quot;">​</a></h3><p>Hai già imparato a conoscere gli obiettivi SMART. Ora gerarchizzali:</p><ol><li><strong>Obiettivo a lungo termine</strong> (1-2 anni): il tuo sogno</li><li><strong>Obiettivo annuale</strong>: Obiettivo di quest&#39;anno</li><li><strong>Obiettivi trimestrali</strong>: traguardi trimestrali</li><li><strong>Obiettivi mensili</strong>: Aree di interesse specifiche</li><li><strong>Obiettivi settimanali</strong>: Obiettivi di allenamento</li></ol><h3 id="fase-2-valuta-le-tue-risorse" tabindex="-1">Fase 2: Valuta le tue risorse <a class="header-anchor" href="#fase-2-valuta-le-tue-risorse" aria-label="Permalink to &quot;Fase 2: Valuta le tue risorse&quot;">​</a></h3><p>Prima di pianificare, valuta onestamente ciò che hai:</p><table tabindex="0"><thead><tr><th>Risorsa</th><th>Domande da porre</th></tr></thead><tbody><tr><td><strong>Tempo</strong></td><td>Quante ore alla settimana puoi realisticamente allenarti?</td></tr><tr><td><strong>Posizione</strong></td><td>Hai accesso a una pista adatta? Qual è la qualità della superficie?</td></tr><tr><td><strong>Attrezzatura</strong></td><td>Hai le bocce adatte? Strumenti di misurazione? Capacità video?</td></tr><tr><td><strong>Conoscenza</strong></td><td>Quali sono i tuoi punti di forza e di debolezza tecnici?</td></tr><tr><td><strong>Condizioni fisiche</strong></td><td>Ci sono limitazioni? Aree che necessitano di lavori?</td></tr></tbody></table><p>Siate onesti. Un piano realistico è meglio di una fantasia ambiziosa.</p><h3 id="fase-3-scegli-i-tuoi-esercizi" tabindex="-1">Fase 3: Scegli i tuoi esercizi <a class="header-anchor" href="#fase-3-scegli-i-tuoi-esercizi" aria-label="Permalink to &quot;Fase 3: Scegli i tuoi esercizi&quot;">​</a></h3><p>Seleziona gli esercizi che supportano direttamente i tuoi obiettivi:</p><p><strong>Per migliorare la puntatura:</strong></p><ul><li>Puntamento di precisione alle zone contrassegnate</li><li>Esercizi di variazione della distanza</li><li>Diverse pratiche di superficie</li></ul><p><strong>Per migliorare le riprese:</strong></p><ul><li>Scala di tiro (distanze progressive)</li><li>Tiro a ostacoli (arco alto forzato)</li><li>Pratica di tiro al bersaglio mobile</li></ul><p><strong>Per lo sviluppo mentale:</strong></p><ul><li>Esercizi di routine pre-tiro</li><li>Sessioni di visualizzazione</li><li>Simulazione della pressione</li></ul><p><strong>Bilancia il tuo programma:</strong></p><ul><li>Lavoro tecnico (puntamento, tiro)</li><li>Allenamento mentale (consapevolezza, visualizzazione)</li><li>Condizionamento fisico (equilibrio, flessibilità)</li><li>Match play (applicazione di abilità)</li></ul><h3 id="fase-4-crea-il-tuo-programma" tabindex="-1">Fase 4: Crea il tuo programma <a class="header-anchor" href="#fase-4-crea-il-tuo-programma" aria-label="Permalink to &quot;Fase 4: Crea il tuo programma&quot;">​</a></h3><p>Crea un programma settimanale realistico:</p>',20)),l(f),c[5]||(c[5]=n('<table tabindex="0"><thead><tr><th>Giorno</th><th>Mattina</th><th>Pomeriggio</th><th>Sera</th><th>Messa a fuoco</th></tr></thead><tbody><tr><td>lun</td><td>-</td><td>Tecnico: Puntamento</td><td>Mobilità leggera</td><td>Precisione</td></tr><tr><td>Martedì</td><td>-</td><td>Tecnico: Riprese</td><td>-</td><td>Potenza/precisione</td></tr><tr><td>Mercoledì</td><td>-</td><td>Allenamento mentale</td><td>-</td><td>Consapevolezza</td></tr><tr><td>Giovedì</td><td>-</td><td>Misto: Scenari di gioco</td><td>Mobilità leggera</td><td>Applicazione</td></tr><tr><td>Ven</td><td>-</td><td>Tecnico: Debolezza</td><td>-</td><td>Miglioramento</td></tr><tr><td>Sab</td><td>Partita o competizione</td><td>-</td><td>-</td><td>Prestazione</td></tr><tr><td>Sole</td><td>Riposo</td><td>Rassegna settimanale</td><td>Pianificazione</td><td>Recupero</td></tr></tbody></table><p><strong>Principi chiave:</strong></p><ul><li>Dare priorità all&#39;allenamento mentale (spesso trascurato)</li><li>Includere i giorni di riposo</li><li>Bilanciare diverse abilità</li><li>Lascia la flessibilità per tutta la vita</li></ul><h3 id="fase-5-prepararsi-agli-ostacoli" tabindex="-1">Fase 5: Prepararsi agli ostacoli <a class="header-anchor" href="#fase-5-prepararsi-agli-ostacoli" aria-label="Permalink to &quot;Fase 5: Prepararsi agli ostacoli&quot;">​</a></h3><p>Le cose andranno male. Preparati.</p><table tabindex="0"><thead><tr><th>Rischio</th><th>Probabilità</th><th>Impatto</th><th>Piano di backup</th></tr></thead><tbody><tr><td>mancanza di tempo</td><td>Alto</td><td>Medio</td><td>Preparare una &quot;seduta minima&quot; (20 min)</td></tr><tr><td>Maltempo</td><td>Medio</td><td>Medio</td><td>Visualizzazione interna, studio video</td></tr><tr><td>Bassa motivazione</td><td>Alto</td><td>Medio</td><td>Torna al &quot;perché&quot;, obiettivi più piccoli, prenditi una pausa</td></tr><tr><td>Lesioni lievi</td><td>Medio</td><td>Alto</td><td>Concentrarsi sull&#39;allenamento mentale, sulle abilità non influenzate</td></tr><tr><td>Nessun partner di pratica</td><td>Medio</td><td>Basso</td><td>Esercizi in solitaria, autoanalisi video</td></tr></tbody></table><h3 id="fase-6-monitora-i-tuoi-progressi" tabindex="-1">Fase 6: monitora i tuoi progressi <a class="header-anchor" href="#fase-6-monitora-i-tuoi-progressi" aria-label="Permalink to &quot;Fase 6: monitora i tuoi progressi&quot;">​</a></h3><p>Ciò che viene misurato viene gestito.</p><p><strong>Tieni un diario di allenamento:</strong></p><ul><li>Data e durata</li><li>Esercizi completati</li><li>Punteggi/risultati</li><li>Come ti sentivi (energia, concentrazione, flusso)</li><li>Note tecniche</li><li>Meteo/condizioni</li></ul><p><strong>Domande di ripasso settimanali:</strong></p><ul><li>Ho completato le sessioni pianificate?</li><li>Quali punteggi ho ottenuto?</li><li>Cosa ti ha fatto sentire bene? Cosa ti ha fatto sentire difficile?</li><li>Avete esperienze di flow?</li><li>Cosa dovrei modificare?</li></ul><h3 id="fase-7-rimani-motivato" tabindex="-1">Fase 7: Rimani motivato <a class="header-anchor" href="#fase-7-rimani-motivato" aria-label="Permalink to &quot;Fase 7: Rimani motivato&quot;">​</a></h3><p>La motivazione è fluttuante. Costruisci sistemi per mantenerla:</p><p><strong>Motivazione interna:</strong></p><ul><li>Connettiti al tuo &quot;perché&quot;</li><li>Festeggia le piccole vittorie</li><li>Notare il miglioramento nel tempo</li><li>Trova gioia nel processo</li></ul><p><strong>Supporto esterno:</strong></p><ul><li>Compagni di allenamento (anche occasionalmente)</li><li>Condividi gli obiettivi con qualcuno</li><li>Unisciti alle comunità online</li><li>Tracciare le serie e la coerenza</li></ul><p><strong>Quando la motivazione cala:</strong></p><ul><li>Fai una sessione minima (qualcosa è meglio di niente)</li><li>Cambia il tuo ambiente</li><li>Rivedi i tuoi progressi</li><li>Ricorda i successi passati</li><li>Prenditi una pausa pianificata se necessario</li></ul><h3 id="fase-8-revisione-e-adattamento" tabindex="-1">Fase 8: Revisione e adattamento <a class="header-anchor" href="#fase-8-revisione-e-adattamento" aria-label="Permalink to &quot;Fase 8: Revisione e adattamento&quot;">​</a></h3><p>Il tuo piano dovrebbe evolversi:</p><p><strong>Settimanale:</strong> Revisione rapida, piccoli aggiustamenti <strong>Mensile:</strong> Valuta i progressi verso gli obiettivi mensili, regola l&#39;attenzione <strong>Trimestrale:</strong> Revisione importante, definizione degli obiettivi del prossimo trimestre <strong>Annualmente:</strong> Valutazione completa, nuovo piano annuale</p><p><strong>Domande per la revisione:</strong></p><ul><li>Sto facendo progressi verso i miei obiettivi?</li><li>Il mio allenamento è efficace?</li><li>Ho bisogno di esercizi diversi?</li><li>I miei obiettivi sono ancora rilevanti?</li><li>Cosa ho imparato?</li></ul><h2 id="esempio-di-piano-di-8-settimane" tabindex="-1">Esempio di piano di 8 settimane <a class="header-anchor" href="#esempio-di-piano-di-8-settimane" aria-label="Permalink to &quot;Esempio di piano di 8 settimane&quot;">​</a></h2><p><strong>Obiettivo:</strong> Migliorare la precisione del tiro del 15%</p><table tabindex="0"><thead><tr><th>Settimana</th><th>Messa a fuoco</th><th>Sessioni chiave</th></tr></thead><tbody><tr><td>1</td><td>Linea di base</td><td>Test del livello attuale, analisi video</td></tr><tr><td>2</td><td>Tecnica</td><td>Identificare e lavorare sulle questioni chiave</td></tr><tr><td>3</td><td>Ripetizione</td><td>Pratica di tiro ad alto volume</td></tr><tr><td>4</td><td>Test</td><td>Valutazione intermedia, regolazione</td></tr><tr><td>5</td><td>Variazione</td><td>Diverse distanze e angoli</td></tr><tr><td>6</td><td>Pressione</td><td>Aggiungere conseguenze alle esercitazioni</td></tr><tr><td>7</td><td>Integrazione</td><td>Scenari simili a giochi</td></tr><tr><td>8</td><td>Prova finale</td><td>Misurare il miglioramento</td></tr></tbody></table><h2 id="conclusione-chiave" tabindex="-1">Conclusione chiave <a class="header-anchor" href="#conclusione-chiave" aria-label="Permalink to &quot;Conclusione chiave&quot;">​</a></h2><blockquote><p>Pianifica il tuo lavoro, poi elabora il piano. Ma sii pronto ad adattarti.</p></blockquote><p>Il piano migliore è quello che seguirai davvero. Inizia in modo semplice, sii coerente e adattalo man mano che impari.</p>',31)),l(b)])}]]);export{c as __pageData,p as default};
